<div class="card"><a href="/stocks">← Kembali</a><h1>{{$stock->name}}</h1><p>SKU: {{$stock->sku??'-'}} · {{$stock->quantity}} {{$stock->unit}} · {{$stock->status}}</p><button class="btn" wire:click="adjust(1)">Tambah qty</button> <button class="btn btn-secondary" wire:click="adjust(-1)">Kurangi qty</button><hr><form wire:submit="save"><label>Nama</label><input class="input" wire:model="stock.name"><label>SKU</label><input class="input" wire:model="stock.sku"><label>Deskripsi (Markdown)</label><textarea class="input" wire:model="stock.description"></textarea><label>Quantity</label><input class="input" type="number" wire:model="stock.quantity"><label>Unit</label><input class="input" wire:model="stock.unit"><label>Price</label><input class="input" type="number" wire:model="stock.price"><label>Minimum stok</label><input class="input" type="number" wire:model="stock.min_stock"><label>Cover</label><input type="file" wire:model="cover"><button class="btn">Simpan</button></form></div>